css:
:scope{--ink:var(--os-color-text);--sans:'Jost', system-ui, sans-serif}
:scope{color:var(--ink);font-family:var(--sans);font-weight:300;font-size:18px;line-height:1.75}
@media (max-width:767px){:scope{font-size:17px}}
:where(h1,h2,h3,h4,h5,h6){color:inherit;font-family:inherit;font-weight:bold;font-style:inherit;letter-spacing:normal;text-transform:none;line-height:inherit;text-wrap:wrap}
:where(h1){font-size:2em}:where(h2){font-size:1.5em}:where(h3){font-size:1.17em}:where(h4){font-size:1em}:where(h5){font-size:.83em}:where(h6){font-size:.67em}
:where(.os-ci){display:inline-block;max-width:100%;vertical-align:middle;aspect-ratio:auto}
.os-ci>picture{display:contents}
.os-ci img{display:block;width:100%;height:100%;object-fit:inherit;object-position:inherit;border-radius:inherit}
*{box-sizing:border-box}
[class~="os-ci"]{max-width:100%;display:block}
img{display:block}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
section{padding:100px 0}
.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:18px;margin-top:32px}
.gallery [class~="os-ci"]{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:16px}
.gallery img{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:16px}
.gallery [class~="os-ci"]:nth-child(odd){border-radius:200px 200px 16px 16px}
.gallery img:nth-child(odd){border-radius:200px 200px 16px 16px}
.gallery.four{grid-template-columns:repeat(auto-fit,minmax(240px,1fr))}
.gallery.four [class~="os-ci"]{aspect-ratio:3/4;border-radius:200px 200px 16px 16px}
.gallery.four img{aspect-ratio:3/4;border-radius:200px 200px 16px 16px}
@media (max-width:767px){section{padding:72px 0}}
@media (max-width:767px){.gallery{grid-template-columns:1fr 1fr;gap:10px}}
@media (max-width:767px){.gallery [class~="os-ci"]{border-radius:12px}}
@media (max-width:767px){.gallery img{border-radius:12px}}
@media (max-width:767px){.gallery [class~="os-ci"]:nth-child(odd){border-radius:100px 100px 12px 12px}}
@media (max-width:767px){.gallery img:nth-child(odd){border-radius:100px 100px 12px 12px}}
:scope:scope:scope .s-1{padding-top:40px}
